// Genuary #09: The textile design patterns of public transport seating

void mainImage(out vec4 C, vec2 U)
{
    vec2 I = floor(100.*U.yy/iResolution.yy);
    C = vec4(
            sqrt(
                vec3(.2)+vec3(.7)*cos(6.28*(floor(iTime*10.)*textureLod(iChannel0, I*.01, 0.).x+vec3(0., .3, .6)))
            ),
            1.);
}
